using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.IO;class IconMaker{static void Main(string[] args){using(var b=new Bitmap(256,256)){using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.Transparent);using(var brush=new SolidBrush(Color.FromArgb(99,86,217)))g.FillEllipse(brush,0,0,256,256);g.TranslateTransform(128,128);g.RotateTransform(-9);g.FillRectangle(new SolidBrush(Color.FromArgb(190,184,240)),-62,-62,136,144);g.RotateTransform(9);g.FillRectangle(Brushes.White,-72,-77,133,146);using(var font=new Font("Yu Gothic",64,FontStyle.Regular,GraphicsUnit.Pixel))g.DrawString("あ",font,new SolidBrush(Color.FromArgb(99,86,217)),-46,-61);using(var pen=new Pen(Color.FromArgb(99,86,217),8)){g.DrawLine(pen,-44,30,33,30);g.DrawLine(pen,-44,48,9,48);}}using(var ms=new MemoryStream()){b.Save(ms,ImageFormat.Png);var bytes=ms.ToArray();using(var f=new BinaryWriter(File.Create(args[0]))){f.Write((short)0);f.Write((short)1);f.Write((short)1);f.Write((byte)0);f.Write((byte)0);f.Write((byte)0);f.Write((byte)0);f.Write((short)1);f.Write((short)32);f.Write(bytes.Length);f.Write(22);f.Write(bytes);}}}}}